nextflow_workflow {

    name "Test Subworkflow BAM_CREATE_SOM_PON_GATK"
    script "../main.nf"
    config "./nextflow.config"

    workflow "BAM_CREATE_SOM_PON_GATK"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bam_create_som_pon_gatk"
    tag "gatk4"
    tag "gatk4/createsomaticpanelofnormals"
    tag "gatk4/genomicsdbimport"
    tag "gatk4/mergemutectstats"
    tag "gatk4/mergevcfs"
    tag "gatk4/mutect2"
    tag "gatk4/splitintervals"

    test("test_create_som_pon_gatk_bam - no_intervals") {
        when {
            workflow {
                """
                // ch_input
                input[0] = channel.of(
                    [
                        [ id:'test1' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true)
                    ],
                    [
                        [ id:'test2' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true)
                    ]
                )
                // ch_fasta
                input[1] = channel.value([ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true)])
                // ch_fai
                input[2] = channel.value([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta.fai', checkIfExists: true),
                    []
                ])
                // ch_dict
                input[3] = channel.value([ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.dict', checkIfExists: true)])
                // str_pon_norm
                input[4] = "test_panel"
                // ch_intervals_gendb
                input[5] = channel.value(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true))
                // ch_intervals_num
                input[6] = channel.value([[], 0])
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(workflow.out).collectEntries{ key, val ->
                        if (key in ["mutect2_index", "mutect2_stats", "mutect2_vcf"]) {
                            def array = [file(val[0][1]).name, file(val[1][1]).name]
                            return [key, array.sort().unique()]
                        } else if (key == "genomicsdb") {
                            return [key, new File(val[0][1][0].toString()).parentFile.name]
                        } else {
                            return [key, file(val[0][1]).name]
                        }
                    }
                ).match() }
            )
        }
    }

    test("test_create_som_pon_gatk_bam - intervals") {
        setup {
            run("GATK4_SPLITINTERVALS") {
                script "../../../../modules/nf-core/gatk4/splitintervals/main.nf"
                process {
                    """
                    input[0] = [ [ id:'test' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true) ]
                    input[1] = [ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true) ]
                    input[2] = [ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta.fai', checkIfExists: true) ]
                    input[3] = [ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.dict', checkIfExists: true) ]
                    """
                }
            }
        }

        when {
            workflow {
                """
                // ch_input
                input[0] = channel.of(
                    [
                        [ id:'test1' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true)
                    ],
                    [
                        [ id:'test2' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true)
                    ]
                )
                // ch_fasta
                input[1] = channel.value([ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true)])
                // ch_fai
                input[2] = channel.value([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta.fai', checkIfExists: true),
                    []
                ])
                // ch_dict
                input[3] = channel.value([ [ id:'genome' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.dict', checkIfExists: true)])
                // str_pon_norm
                input[4] = "test_panel"
                // ch_intervals_gendb
                input[5] = channel.value(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true))
                // ch_intervals_num
                input[6] = GATK4_SPLITINTERVALS.out.split_intervals
                    .flatMap { _meta, intervals -> intervals.collect { interval -> [ interval, intervals.size() ] } }
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(workflow.out).collectEntries{ key, val ->
                        if (key in ["mutect2_index", "mutect2_stats", "mutect2_vcf"]) {
                            def array = [file(val[0][1]).name, file(val[1][1]).name]
                            return [key, array.sort().unique()]
                        } else if (key == "genomicsdb") {
                            return [key, new File(val[0][1][0].toString()).parentFile.name]
                        } else {
                            return [key, file(val[0][1]).name]
                        }
                    }
                ).match() }
            )
        }
    }
}

process {
    withName: GATK4_SPLITINTERVALS {
        ext.args = "--scatter-count 3"
    }
    withName: GATK4_MUTECT2 {
        ext.args = "--max-mnp-distance 0"
        ext.prefix = { meta.num_intervals <= 1 ? "${meta.id}" : "${meta.id}.mutect2.${intervals.baseName}" }
    }
}
